-- Up Migration
-- Initial versioned schema, promoted from the reviewed F2 design.
-- UUIDs are generated by the application. Core PostgreSQL features only.
-- Hosting roles/grants, auth-adapter tables and retention jobs are separate.
CREATE SCHEMA newbert;
SET LOCAL search_path = newbert, public;

CREATE TABLE app_users (
  id uuid PRIMARY KEY,
  auth_issuer text NOT NULL,
  auth_subject text NOT NULL,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','disabled','deletion_pending')),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(auth_issuer, auth_subject)
);
CREATE TABLE workspaces (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL UNIQUE REFERENCES app_users(id),
  timezone text NOT NULL DEFAULT 'Asia/Kolkata',
  revision bigint NOT NULL DEFAULT 1 CHECK(revision > 0),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE workspace_dispatch (
  workspace_id uuid PRIMARY KEY REFERENCES workspaces(id),
  last_claimed_at timestamptz,
  active_count integer NOT NULL DEFAULT 0 CHECK(active_count >= 0)
);
CREATE TABLE provider_connections (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL REFERENCES workspaces(id),
  provider text NOT NULL CHECK(provider IN ('elevenlabs')),
  status text NOT NULL DEFAULT 'pending_validation'
    CHECK(status IN ('pending_validation','active','invalid','revoked')),
  secret_ref text NOT NULL,
  secret_version text NOT NULL,
  revision bigint NOT NULL DEFAULT 1,
  last_checked_at timestamptz,
  safe_error_code text,
  revoked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(workspace_id,id)
);
CREATE UNIQUE INDEX one_current_personal_provider ON provider_connections(workspace_id,provider)
  WHERE status IN ('pending_validation','active','invalid');
CREATE TABLE projects (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL REFERENCES workspaces(id),
  title text NOT NULL CHECK(length(title) BETWEEN 1 AND 160),
  status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),
  revision bigint NOT NULL DEFAULT 1 CHECK(revision > 0),
  next_version_number integer NOT NULL DEFAULT 1 CHECK(next_version_number > 0),
  latest_output_artifact_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(workspace_id,id)
);
CREATE INDEX projects_list ON projects(workspace_id,updated_at DESC,id DESC);
CREATE TABLE project_drafts (
  workspace_id uuid NOT NULL,
  project_id uuid PRIMARY KEY,
  revision bigint NOT NULL DEFAULT 1 CHECK(revision > 0),
  schema_version integer NOT NULL CHECK(schema_version > 0),
  content jsonb NOT NULL CHECK(jsonb_typeof(content) = 'object'),
  updated_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id)
);
CREATE TABLE project_versions (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL,
  project_id uuid NOT NULL,
  version_number integer NOT NULL CHECK(version_number > 0),
  source_draft_revision bigint NOT NULL CHECK(source_draft_revision > 0),
  schema_version integer NOT NULL CHECK(schema_version > 0),
  input_snapshot jsonb NOT NULL CHECK(jsonb_typeof(input_snapshot) = 'object'),
  input_hash text NOT NULL CHECK(input_hash ~ '^[0-9a-f]{64}$'),
  mode text NOT NULL CHECK(mode IN ('guided','automatic')),
  approval_actor_id uuid REFERENCES app_users(id),
  approved_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK((approval_actor_id IS NULL) = (approved_at IS NULL)),
  UNIQUE(workspace_id,id), UNIQUE(workspace_id,project_id,id),
  UNIQUE(project_id,version_number),
  FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id)
);
CREATE FUNCTION reject_version_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'Submitted project versions are immutable'; END;
$$;
CREATE TRIGGER immutable_version BEFORE UPDATE OR DELETE ON project_versions
  FOR EACH ROW EXECUTE FUNCTION reject_version_mutation();

CREATE TABLE generation_jobs (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL,
  project_id uuid NOT NULL,
  version_id uuid NOT NULL,
  kind text NOT NULL CHECK(kind IN ('ideation','plan','produce')),
  state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','paused','succeeded','failed','cancelled')),
  stage text CHECK(stage IN ('ideating','researching','scripting','planning_scenes','generating_voice','aligning','composing','rendering','checking')),
  revision bigint NOT NULL DEFAULT 1 CHECK(revision > 0),
  retry_of_job_id uuid,
  provider_connection_id uuid,
  provider_binding jsonb NOT NULL DEFAULT '{}'::jsonb,
  operation_key uuid NOT NULL,
  eligible_at timestamptz NOT NULL DEFAULT now(),
  pause_reason text,
  safe_error_code text,
  cancel_requested_at timestamptz,
  lease_owner text,
  lease_expires_at timestamptz,
  lease_token bigint NOT NULL DEFAULT 0 CHECK(lease_token >= 0),
  stage_checkpoint jsonb NOT NULL DEFAULT '{}'::jsonb,
  output_artifact_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  UNIQUE(workspace_id,id), UNIQUE(workspace_id,project_id,id),
  UNIQUE(workspace_id,project_id,version_id,id),
  UNIQUE(workspace_id,operation_key),
  FOREIGN KEY(workspace_id,project_id,version_id) REFERENCES project_versions(workspace_id,project_id,id),
  FOREIGN KEY(workspace_id,project_id,version_id,retry_of_job_id) REFERENCES generation_jobs(workspace_id,project_id,version_id,id),
  FOREIGN KEY(workspace_id,provider_connection_id) REFERENCES provider_connections(workspace_id,id),
  CHECK((lease_owner IS NULL) = (lease_expires_at IS NULL)),
  CHECK(state <> 'paused' OR pause_reason IS NOT NULL)
);
CREATE UNIQUE INDEX one_active_job_per_project ON generation_jobs(project_id)
  WHERE state IN ('queued','running','paused');
CREATE INDEX runnable_jobs ON generation_jobs(eligible_at,created_at,id) WHERE state = 'queued';
CREATE INDEX workspace_jobs ON generation_jobs(workspace_id,created_at DESC,id DESC);
CREATE INDEX expired_job_leases ON generation_jobs(lease_expires_at) WHERE state = 'running';

CREATE TABLE discussion_messages (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL,
  project_id uuid NOT NULL,
  job_id uuid,
  role text NOT NULL CHECK(role IN ('user','assistant')),
  content text NOT NULL CHECK(length(content) BETWEEN 1 AND 12000),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(workspace_id,id),
  FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id),
  FOREIGN KEY(workspace_id,project_id,job_id) REFERENCES generation_jobs(workspace_id,project_id,id)
);
CREATE INDEX messages_history ON discussion_messages(workspace_id,project_id,created_at DESC,id DESC);

CREATE TABLE artifacts (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL,
  project_id uuid NOT NULL,
  version_id uuid NOT NULL,
  job_id uuid NOT NULL,
  kind text NOT NULL CHECK(kind IN ('research','storyboard','audio','alignment','composition','captions','video','validation','visual_asset')),
  storage_key text NOT NULL UNIQUE,
  content_hash text NOT NULL CHECK(content_hash ~ '^[0-9a-f]{64}$'),
  input_fingerprint text NOT NULL CHECK(input_fingerprint ~ '^[0-9a-f]{64}$'),
  mime_type text NOT NULL,
  byte_size bigint NOT NULL CHECK(byte_size >= 0),
  duration_ms bigint CHECK(duration_ms > 0),
  validation_status text NOT NULL DEFAULT 'pending' CHECK(validation_status IN ('pending','passed','failed')),
  storage_status text NOT NULL DEFAULT 'available' CHECK(storage_status IN ('available','deleting','deleted')),
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  retain_until timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  UNIQUE(workspace_id,id), UNIQUE(workspace_id,project_id,id),
  UNIQUE(workspace_id,project_id,version_id,id),
  UNIQUE(workspace_id,project_id,version_id,job_id,id),
  FOREIGN KEY(workspace_id,project_id,version_id,job_id) REFERENCES generation_jobs(workspace_id,project_id,version_id,id)
);
CREATE INDEX reusable_artifacts ON artifacts(workspace_id,kind,input_fingerprint)
  WHERE validation_status = 'passed' AND storage_status = 'available';
CREATE INDEX version_artifacts ON artifacts(workspace_id,version_id,created_at,id);
ALTER TABLE projects ADD CONSTRAINT project_output_same_project
  FOREIGN KEY(workspace_id,id,latest_output_artifact_id) REFERENCES artifacts(workspace_id,project_id,id);
ALTER TABLE generation_jobs ADD CONSTRAINT job_output_same_job
  FOREIGN KEY(workspace_id,project_id,version_id,id,output_artifact_id)
  REFERENCES artifacts(workspace_id,project_id,version_id,job_id,id);
CREATE TABLE artifact_dependencies (
  workspace_id uuid NOT NULL,
  artifact_id uuid NOT NULL,
  depends_on_id uuid NOT NULL,
  PRIMARY KEY(artifact_id,depends_on_id),
  CHECK(artifact_id <> depends_on_id),
  FOREIGN KEY(workspace_id,artifact_id) REFERENCES artifacts(workspace_id,id),
  FOREIGN KEY(workspace_id,depends_on_id) REFERENCES artifacts(workspace_id,id)
);
CREATE INDEX artifact_reverse_dependencies ON artifact_dependencies(workspace_id,depends_on_id);
CREATE TABLE job_attempts (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL,
  job_id uuid NOT NULL,
  stage text NOT NULL,
  attempt_number integer NOT NULL CHECK(attempt_number > 0),
  state text NOT NULL CHECK(state IN ('prepared','submitted','succeeded','failed','unknown')),
  request_fingerprint text NOT NULL CHECK(request_fingerprint ~ '^[0-9a-f]{64}$'),
  provider text,
  provider_request_id text,
  result_artifact_id uuid,
  lease_token bigint NOT NULL,
  safe_error_code text,
  started_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  UNIQUE(job_id,stage,attempt_number),
  FOREIGN KEY(workspace_id,job_id) REFERENCES generation_jobs(workspace_id,id),
  FOREIGN KEY(workspace_id,result_artifact_id) REFERENCES artifacts(workspace_id,id)
);

CREATE TABLE sources (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL,
  version_id uuid NOT NULL,
  title text NOT NULL,
  url text NOT NULL,
  retrieved_at timestamptz NOT NULL,
  content_hash text CHECK(content_hash ~ '^[0-9a-f]{64}$'),
  excerpt text,
  UNIQUE(workspace_id,version_id,id),
  FOREIGN KEY(workspace_id,version_id) REFERENCES project_versions(workspace_id,id)
);
CREATE TABLE claims (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL,
  version_id uuid NOT NULL,
  scene_id uuid,
  claim_text text NOT NULL,
  classification text NOT NULL CHECK(classification IN ('factual','interpretation','illustrative')),
  status text NOT NULL CHECK(status IN ('supported','needs_review','unsupported')),
  blocking boolean NOT NULL DEFAULT true,
  UNIQUE(workspace_id,version_id,id),
  FOREIGN KEY(workspace_id,version_id) REFERENCES project_versions(workspace_id,id)
);
CREATE TABLE claim_sources (
  workspace_id uuid NOT NULL,
  version_id uuid NOT NULL,
  claim_id uuid NOT NULL,
  source_id uuid NOT NULL,
  locator text,
  PRIMARY KEY(claim_id,source_id),
  FOREIGN KEY(workspace_id,version_id,claim_id) REFERENCES claims(workspace_id,version_id,id),
  FOREIGN KEY(workspace_id,version_id,source_id) REFERENCES sources(workspace_id,version_id,id)
);

CREATE TABLE usage_buckets (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL REFERENCES workspaces(id),
  resource text NOT NULL CHECK(resource IN ('generation_count','narration_ms','render_ms','storage_bytes','provider_credits')),
  period_start timestamptz NOT NULL,
  period_end timestamptz NOT NULL,
  limit_units bigint NOT NULL CHECK(limit_units >= 0),
  reserved_units bigint NOT NULL DEFAULT 0 CHECK(reserved_units >= 0),
  used_units bigint NOT NULL DEFAULT 0 CHECK(used_units >= 0),
  CHECK(period_end > period_start),
  UNIQUE(workspace_id,id), UNIQUE(workspace_id,resource,period_start)
  -- Actual incurred usage may exceed a limit: record reality and block admission.
);
CREATE TABLE usage_reservations (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL,
  job_id uuid NOT NULL,
  bucket_id uuid NOT NULL,
  reservation_key text NOT NULL,
  reserved_units bigint NOT NULL CHECK(reserved_units >= 0),
  actual_units bigint CHECK(actual_units >= 0),
  status text NOT NULL DEFAULT 'reserved' CHECK(status IN ('reserved','settled','released','reconciliation_required')),
  created_at timestamptz NOT NULL DEFAULT now(),
  settled_at timestamptz,
  UNIQUE(workspace_id,id), UNIQUE(job_id,bucket_id,reservation_key),
  FOREIGN KEY(workspace_id,job_id) REFERENCES generation_jobs(workspace_id,id),
  FOREIGN KEY(workspace_id,bucket_id) REFERENCES usage_buckets(workspace_id,id)
);
CREATE TABLE usage_entries (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL,
  reservation_id uuid NOT NULL,
  event_key text NOT NULL,
  entry_type text NOT NULL CHECK(entry_type IN ('incurred','adjustment')),
  units_delta bigint NOT NULL,
  provider_units bigint CHECK(provider_units >= 0),
  provider_unit text,
  cost_microunits bigint CHECK(cost_microunits >= 0),
  currency char(3),
  reason_code text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(workspace_id,event_key),
  CHECK(entry_type <> 'incurred' OR units_delta >= 0),
  FOREIGN KEY(workspace_id,reservation_id) REFERENCES usage_reservations(workspace_id,id)
);
CREATE INDEX usage_history ON usage_entries(workspace_id,created_at DESC,id DESC);
-- Platform budget has independent rows and internal-only access.
CREATE TABLE platform_budgets (
  id uuid PRIMARY KEY,
  resource text NOT NULL,
  period_start timestamptz NOT NULL,
  period_end timestamptz NOT NULL,
  limit_units bigint NOT NULL CHECK(limit_units >= 0),
  reserved_units bigint NOT NULL DEFAULT 0 CHECK(reserved_units >= 0),
  used_units bigint NOT NULL DEFAULT 0 CHECK(used_units >= 0),
  CHECK(period_end > period_start), UNIQUE(resource,period_start)
);
CREATE TABLE platform_reservations (
  id uuid PRIMARY KEY,
  job_id uuid NOT NULL REFERENCES generation_jobs(id),
  budget_id uuid NOT NULL REFERENCES platform_budgets(id),
  event_key text NOT NULL UNIQUE,
  reserved_units bigint NOT NULL CHECK(reserved_units >= 0),
  actual_units bigint CHECK(actual_units >= 0),
  status text NOT NULL CHECK(status IN ('reserved','settled','released','reconciliation_required')),
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE instagram_connections (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL REFERENCES workspaces(id),
  remote_account_id text NOT NULL,
  display_name text NOT NULL,
  status text NOT NULL CHECK(status IN ('active','reauth_required','disconnected')),
  secret_ref text NOT NULL,
  granted_scopes text[] NOT NULL,
  expires_at timestamptz,
  revision bigint NOT NULL DEFAULT 1,
  created_at timestamptz NOT NULL DEFAULT now(),
  disconnected_at timestamptz,
  UNIQUE(workspace_id,id)
);
CREATE UNIQUE INDEX one_current_instagram_per_workspace ON instagram_connections(workspace_id)
  WHERE status IN ('active','reauth_required');
CREATE UNIQUE INDEX one_current_owner_per_instagram ON instagram_connections(remote_account_id)
  WHERE status IN ('active','reauth_required');
CREATE TABLE oauth_states (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL REFERENCES workspaces(id),
  state_hash text NOT NULL UNIQUE CHECK(state_hash ~ '^[0-9a-f]{64}$'),
  session_binding_hash text NOT NULL CHECK(session_binding_hash ~ '^[0-9a-f]{64}$'),
  verifier_secret_ref text,
  return_path text NOT NULL,
  expires_at timestamptz NOT NULL,
  consumed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE publish_intents (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL,
  project_id uuid NOT NULL,
  version_id uuid NOT NULL,
  connection_id uuid NOT NULL,
  connection_revision bigint NOT NULL,
  video_artifact_id uuid,
  production_job_id uuid,
  caption text NOT NULL,
  payload_hash text NOT NULL CHECK(payload_hash ~ '^[0-9a-f]{64}$'),
  authorized_by uuid NOT NULL REFERENCES app_users(id),
  authorized_at timestamptz NOT NULL,
  state text NOT NULL CHECK(state IN ('awaiting_output','scheduled','queued','publishing','paused','published','failed','cancelled','reconciliation_required')),
  revision bigint NOT NULL DEFAULT 1 CHECK(revision > 0),
  late_policy text NOT NULL CHECK(late_policy IN ('bounded_window','publish_when_ready')),
  late_tolerance_seconds integer NOT NULL DEFAULT 0 CHECK(late_tolerance_seconds BETWEEN 0 AND 86400),
  remote_media_id text,
  permalink text,
  cancel_requested_at timestamptz,
  pause_reason text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK(video_artifact_id IS NOT NULL OR production_job_id IS NOT NULL),
  UNIQUE(workspace_id,id),
  FOREIGN KEY(workspace_id,project_id,version_id) REFERENCES project_versions(workspace_id,project_id,id),
  FOREIGN KEY(workspace_id,connection_id) REFERENCES instagram_connections(workspace_id,id),
  FOREIGN KEY(workspace_id,project_id,version_id,production_job_id) REFERENCES generation_jobs(workspace_id,project_id,version_id,id),
  FOREIGN KEY(workspace_id,project_id,version_id,video_artifact_id) REFERENCES artifacts(workspace_id,project_id,version_id,id)
  -- Service validates artifact kind/validation and pending-job binding.
);
CREATE TABLE publication_schedules (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL,
  intent_id uuid NOT NULL UNIQUE,
  scheduled_at timestamptz NOT NULL,
  timezone text NOT NULL,
  revision bigint NOT NULL DEFAULT 1,
  state text NOT NULL CHECK(state IN ('scheduled','claimed','completed','paused','cancelled')),
  lease_owner text,
  lease_expires_at timestamptz,
  lease_token bigint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY(workspace_id,intent_id) REFERENCES publish_intents(workspace_id,id)
);
CREATE INDEX due_schedules ON publication_schedules(scheduled_at,id) WHERE state = 'scheduled';
CREATE INDEX workspace_intents ON publish_intents(workspace_id,created_at DESC,id DESC);
CREATE INDEX artifact_publish_holds ON publish_intents(workspace_id,video_artifact_id,state);
CREATE TABLE publish_attempts (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL,
  intent_id uuid NOT NULL,
  attempt_number integer NOT NULL CHECK(attempt_number > 0),
  operation_key uuid NOT NULL UNIQUE,
  phase text NOT NULL CHECK(phase IN ('container','processing','publish','reconcile')),
  state text NOT NULL CHECK(state IN ('prepared','submitted','confirmed_success','confirmed_failure','unknown')),
  request_hash text NOT NULL CHECK(request_hash ~ '^[0-9a-f]{64}$'),
  remote_container_id text,
  remote_media_id text,
  safe_error_code text,
  lease_token bigint NOT NULL,
  started_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  UNIQUE(intent_id,attempt_number),
  FOREIGN KEY(workspace_id,intent_id) REFERENCES publish_intents(workspace_id,id)
);
CREATE UNIQUE INDEX one_unresolved_publish_attempt ON publish_attempts(intent_id)
  WHERE state IN ('prepared','submitted','unknown');
CREATE TABLE idempotency_records (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL REFERENCES workspaces(id),
  operation text NOT NULL,
  client_key text NOT NULL CHECK(length(client_key) BETWEEN 1 AND 128),
  request_hash text NOT NULL CHECK(request_hash ~ '^[0-9a-f]{64}$'),
  response_status integer CHECK(response_status BETWEEN 200 AND 299),
  response_body jsonb,
  response_location text,
  resource_type text,
  resource_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  UNIQUE(workspace_id,operation,client_key)
);
CREATE TABLE outbox_events (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL REFERENCES workspaces(id),
  event_key text NOT NULL UNIQUE,
  event_type text NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}'::jsonb,
  available_at timestamptz NOT NULL DEFAULT now(),
  lease_owner text,
  lease_expires_at timestamptz,
  attempt_count integer NOT NULL DEFAULT 0 CHECK(attempt_count >= 0),
  delivered_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX undelivered_outbox ON outbox_events(available_at,id) WHERE delivered_at IS NULL;
CREATE TABLE audit_events (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL REFERENCES workspaces(id),
  actor_user_id uuid REFERENCES app_users(id),
  action text NOT NULL,
  target_type text NOT NULL,
  target_id uuid NOT NULL,
  request_id uuid NOT NULL,
  safe_metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_history ON audit_events(workspace_id,created_at DESC,id DESC);

-- No grants are made here. Roles and bootstrap membership resolution are an
-- implementation gate. Never connect the web API as migration owner/superuser.
CREATE FUNCTION current_workspace_id() RETURNS uuid
  LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.workspace_id',true),'')::uuid $$;
ALTER TABLE workspaces ENABLE ROW LEVEL SECURITY;
ALTER TABLE workspaces FORCE ROW LEVEL SECURITY;
CREATE POLICY workspace_isolation ON workspaces USING(id = current_workspace_id()) WITH CHECK(id = current_workspace_id());
DO $$
DECLARE tab text;
BEGIN
  FOREACH tab IN ARRAY ARRAY[
    'workspace_dispatch','provider_connections','projects','project_drafts','project_versions',
    'generation_jobs','discussion_messages','artifacts','artifact_dependencies','job_attempts',
    'sources','claims','claim_sources','usage_buckets','usage_reservations','usage_entries',
    'instagram_connections','oauth_states','publish_intents','publication_schedules',
    'publish_attempts','idempotency_records','outbox_events','audit_events'
  ] LOOP
    EXECUTE format('ALTER TABLE newbert.%I ENABLE ROW LEVEL SECURITY',tab);
    EXECUTE format('ALTER TABLE newbert.%I FORCE ROW LEVEL SECURITY',tab);
    EXECUTE format('CREATE POLICY tenant_isolation ON newbert.%I USING (workspace_id = newbert.current_workspace_id()) WITH CHECK (workspace_id = newbert.current_workspace_id())',tab);
  END LOOP;
END $$;

-- Down Migration
DO $$ BEGIN RAISE EXCEPTION 'Forward-only migration. Use a reviewed forward fix.'; END $$;
